const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const arctic = ee.Geometry.Polygon([
    [[-180, 63], [180, 63], [180, 90], [-180, 90], [-180, 63]]
  ]);

  const date2011 = ee.DateRange('2011-04-01', '2011-04-30');
  const date2014 = ee.DateRange('2014-04-01', '2014-04-30');

  // 2. Data Acquisition - Using TOMS/OMI Ozone data
  let col2011 = ee.ImageCollection('TOMS/MERGED')
    .filterDate(date2011)
    .filterBounds(arctic);

  let col2014 = ee.ImageCollection('TOMS/MERGED')
    .filterDate(date2014)
    .filterBounds(arctic);

  const size2011 = col2011.size().getInfo();
  const size2014 = col2014.size().getInfo();

  console.log(`2011 Images: ${size2011}`);
  console.log(`2014 Images: ${size2014}`);

  if (size2011 === 0 || size2014 === 0) {
    console.log("Empty collection for one or both periods.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean ozone
  const img2011 = col2011.mean();
  const img2014 = col2014.mean();

  // Check pixel counts
  const count2011 = img2011.select('ozone').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: arctic,
    scale: 50000,
    maxPixels: 1e9
  }).get('ozone').getInfo();

  const count2014 = img2014.select('ozone').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: arctic,
    scale: 50000,
    maxPixels: 1e9
  }).get('ozone').getInfo();

  console.log(`2011 Valid Pixels: ${count2011}`);
  console.log(`2014 Valid Pixels: ${count2014}`);

  if (count2011 === 0 || count2014 === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculate mean ozone values
  const ozone2011 = img2011.select('ozone').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: arctic,
    scale: 50000,
    maxPixels: 1e9
  }).get('ozone').getInfo();

  const ozone2014 = img2014.select('ozone').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: arctic,
    scale: 50000,
    maxPixels: 1e9
  }).get('ozone').getInfo();

  console.log(`April 2011 Mean Ozone: ${ozone2011} DU`);
  console.log(`April 2014 Mean Ozone: ${ozone2014} DU`);

  // 5. Validation & Final Answer
  if (ozone2011 === null || ozone2014 === null || 
      isNaN(ozone2011) || isNaN(ozone2014) ||
      ozone2011 < 0 || ozone2014 < 0 ||
      ozone2011 > 1000 || ozone2014 > 1000) {
    console.log("Invalid ozone values detected.");
    console.log("<answer>C3</answer>");
    return;
  }

  const increase = ozone2014 - ozone2011;
  console.log(`Difference (2014-2011): ${increase.toFixed(2)} DU`);

  if (ozone2014 > ozone2011) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
